<script setup>
import ParticipationTabs from './ParticipationTabs.vue';
import RegistrationActions from './RegistrationActions.vue';
import ListPager from './ListPager.vue';
import PagedRecords from './PagedRecords.vue';
import TargetsPanel from './TargetsPanel.vue';
import RegistrationFilters from './RegistrationFilters.vue';
import ReportStamp from './ReportStamp.vue';
// Native-style mobile composition adapted from MDS DashboardPageMobile/ListPageMobile.
import {computed,nextTick,ref,watch} from 'vue';import {s,title,canAdmin,canEdit,isSuper,canCreateEvent,nav,visibleNav,openAdminSettings,run,navigate,selectEvent,showEventList,reports,number,dateText,roleNames,callLabel,modeLabel,responseLabel,utmContent,loadRows,editRow,openContact,setRole,saveEvent,refreshLatest,resetFilters,resetRowFilters} from './store';
import MMobileTopBar from './mobile/MMobileTopBar.vue';import MMobileBottomNav from './mobile/MMobileBottomNav.vue';import ReportFilters from './ReportFilters.vue';import ChartPanel from './ChartPanel.vue';import KpiCard from './KpiCard.vue';import SettingsFields from './SettingsFields.vue';import ImportFields from './ImportFields.vue';import MemberImport from './MemberImport.vue';
const more=ref(false),sheet=ref('');
const sheetOpen=computed({get:()=>!!sheet.value,set:value=>{if(!value)sheet.value='';}});
const sheetTitle=computed(()=>({actions:'Thao tác báo cáo',filters:'Bộ lọc báo cáo',rows:'Bộ lọc đăng ký',metadata:'Thông tin dữ liệu'})[sheet.value]||'');
const reportFilterCount=computed(()=>Object.values(s.filters).filter(v=>v&&v!=='all').length+Object.keys(s.sources).length);
const rowFilterCount=computed(()=>Object.values(s.rowFilters).filter(v=>v?.length).length+Number(!!s.rowFrom)+Number(!!s.rowTo));
function openActions(){if(!more.value&&s.route==='tong-quan')sheet.value='actions';else more.value=!more.value;}
function refresh(){sheet.value='';refreshLatest();}
async function create(){sheet.value='';await nextTick();s.dialog='new-event';}
watch([()=>s.event?.id,()=>s.route],()=>{sheet.value='';});const items=[{key:'tong-quan',label:'Tổng quan',icon:'home'},{key:'du-lieu',label:'Dữ liệu',icon:'list'},{key:'nguon-du-lieu',label:'Nhập liệu',icon:'upload'},{key:'thanh-vien',label:'Thành viên',icon:'users'},{key:'more',label:'Thêm',icon:'menu-2'}];
function go(key){if(key==='more'){more.value=true;return;}more.value=false;run(()=>navigate(key));}
function back(){if(sheet.value){sheet.value='';return;}if(more.value){more.value=false;return;}if(s.route!=='tong-quan'){go('tong-quan');return;}run(()=>showEventList());}
</script><template><div class="mds-mobile-app relative flex h-full flex-col overflow-hidden" :inert="sheetOpen||!!s.dialog||undefined"><MMobileTopBar :title="more?'Thêm':title" back-label="Quay lại" show-more @back="back" @more="openActions"><template #actions><MButton v-if="!more&&s.route==='tong-quan'" variant="icon" :aria-label="'Bộ lọc báo cáo'+(reportFilterCount?' ('+reportFilterCount+')':'')" :aria-expanded="sheet==='filters'" @click="sheet='filters'"><template #icon><MIcon name="filter" :size="24"/></template><span v-if="reportFilterCount" class="mobile-filter-count">{{reportFilterCount}}</span></MButton></template></MMobileTopBar><main class="scroll-region page-body stack"><div v-if="s.error" role="alert" class="error">{{s.error}}</div><div v-if="s.message" role="status" class="notice">{{s.message}}</div><progress v-if="s.busy" aria-label="Đang xử lý"/>
<template v-if="more"><section class="card stack"><h2>{{s.user.name}}</h2><p class="muted">{{s.user.email}}</p><MButton variant="secondary" @click="run(()=>showEventList())">Chọn sự kiện</MButton><MButton variant="primary" v-if="canCreateEvent" @click="s.dialog='new-event'">Tạo sự kiện</MButton><MButton v-if="canEdit" variant="secondary" @click="more=false;run(()=>navigate('muc-tieu'))">Thiết lập sự kiện</MButton><MButton v-if="isSuper" variant="secondary" @click="openAdminSettings">Thiết lập thành viên</MButton><MButton variant="secondary" @click="s.appearance=true">Giao diện</MButton><MButton variant="secondary" @click="s.dialog='account'">Tài khoản & mật khẩu</MButton></section></template>
<template v-else><div class="mobile-event-picker"><MCombobox aria-label="Chọn sự kiện" :model-value="s.event?.id" :options="s.events.map(e=>({value:e.id,label:e.name}))" @update:model-value="run(()=>selectEvent($event))"/></div><MEmptyState v-if="!s.event" type="initial" title="Chọn sự kiện để bắt đầu"/>
<template v-else-if="s.route==='tong-quan'"><ParticipationTabs mobile/><MTabs class="mobile-report-tabs" :model-value="s.reportTab" :tabs="[{key:'chart',label:'Dashboard'},{key:'table',label:'Số liệu'},{key:'targets',label:'Mục tiêu'}]" @update:model-value="s.reportTab=$event;s.table=$event==='table'"/><div v-if="s.reportBusy" role="status" class="row card"><MSpinner/>Đang cập nhật số liệu…</div><div v-else-if="s.report" data-report class="stack"><ReportStamp :open="false"/><div v-if="!s.report.snapshot.id" class="notice">Chưa có dữ liệu để tổng hợp. Chọn Nhập dữ liệu để bắt đầu.</div><div v-else-if="!s.report.current.total" class="notice">Không có đăng ký phù hợp. Mở bộ lọc và chọn “Xóa bộ lọc” để xem toàn bộ.</div><p v-if="s.report.current.invited" class="muted">{{number(s.report.current.invited)}} khách đã mời chưa đăng ký; chưa cộng vào KPI.</p><TargetsPanel v-if="s.reportTab==='targets'" mobile /><template v-else><div class="kpi-grid"><KpiCard v-for="kind in ['total','completion','clevel','ratio','call_rate',...(s.event.mode==='hybrid'&&s.filters.mode==='all'?['online','offline']:[])]" :key="kind" :kind="kind"/></div><p v-if="s.event.mode==='hybrid'&&s.report.current.modes.find(m=>m.value==='unknown')?.count" class="notice">{{number(s.report.current.modes.find(m=>m.value==='unknown').count)}} đăng ký chưa có hình thức tham dự, chưa tính vào Online hoặc Offline.</p><p v-if="s.event.mode==='hybrid'&&s.report.current.modes.find(m=>m.value==='both')?.count" class="muted">Khách chọn cả hai được tính vào Online và Offline; tổng hai ô có thể lớn hơn tổng đăng ký.</p><div class="mobile-chart-grid"><ChartPanel v-if="s.selected.includes('positions')" class="mobile-composition-card" mobile title="Cơ cấu chức vụ" :rows="s.report.current.positions" :table="s.table" pie/><ChartPanel v-if="s.selected.includes('sizes')" mobile title="Quy mô doanh nghiệp" :rows="s.report.current.sizes" :table="s.table"/><ChartPanel v-if="s.selected.includes('trend')" mobile trend title="Xu hướng đăng ký" :rows="s.report.current.trend.map(r=>({...r,label:dateText(r.label),percent:s.report.current.total?r.count/s.report.current.total*100:0}))" :table="s.table"/><ChartPanel v-if="s.selected.includes('sources')" mobile compact source title="Nguồn khách" :rows="s.report.current.sourceBreakdowns.find(d=>d.name===s.dimension)?.values||[]" :table="s.table"><template #controls><MCombobox v-model="s.dimension" aria-label="Chiều nguồn khách" :options="s.report.sourceDimensions.map(d=>({value:d.name,label:d.name}))"/></template></ChartPanel></div></template></div></template>
<template v-else-if="s.route==='thanh-vien'"><MemberImport/><PagedRecords :key="s.event.id" :rows="s.members" v-slot="{rows:pageRows}"><section class="card mobile-list"><article v-for="m in pageRows" :key="m.id"><h3>{{m.name}}</h3><p>{{m.email}}</p><div class="row mt-3"><span>{{roleNames[m.role]}}</span><MButton v-if="isSuper||(canAdmin&&m.role==='editor')" variant="link" @click="s.editMember=m;s.dialog='remove-member'">Thu hồi quyền</MButton></div></article><MEmptyState v-if="!s.members.length" type="initial" title="Chưa cấp quyền chỉnh sửa"/></section></PagedRecords></template>
<template v-else-if="s.route==='du-lieu'"><ParticipationTabs registrations mobile/><RegistrationActions/><div class="mobile-search-row"><MInput v-model="s.query" placeholder="Tìm khách đăng ký" aria-label="Tìm đăng ký" @keyup.enter="s.page=1;run(loadRows)"/><MButton variant="secondary" :aria-expanded="sheet==='rows'" aria-label="Bộ lọc đăng ký" @click="sheet='rows'"><template #icon><MIcon name="filter" :size="20"/></template>Lọc<span v-if="rowFilterCount"> ({{rowFilterCount}})</span></MButton></div><div class="mobile-results-summary"><span>{{number(s.rowTotal)}} đăng ký<span v-if="rowFilterCount"> · {{rowFilterCount}} bộ lọc</span></span><MButton v-if="rowFilterCount||s.query" variant="link" @click="resetRowFilters">Xóa lọc</MButton><MSpinner v-if="s.rowsBusy"/></div><section class="card mobile-list registration-cards" :aria-busy="s.rowsBusy"><article v-for="r in s.rows" :key="r.id"><div class="mobile-record-heading"><h3>{{r.name||'Chưa có tên'}}</h3><MButton v-if="r.can_edit" variant="icon" aria-label="Chỉnh sửa đăng ký" @click="editRow(r)"><template #icon><MIcon name="pencil" :size="20"/></template></MButton></div><dl><template v-if="s.event.mode==='hybrid'"><dt>Tham dự</dt><dd>{{modeLabel(r.attendance_mode)}}</dd></template><dt>Số điện thoại</dt><dd>{{r.phone||'—'}}</dd><template v-if="s.rowHasTaxId"><dt>Mã số thuế</dt><dd>{{r.tax_id||'—'}}</dd></template><dt>Công ty</dt><dd>{{r.company||'—'}}</dd><dt>Chức vụ</dt><dd>{{r.position||'—'}}</dd><dt>Ngày submit</dt><dd>{{dateText(r.submitted_at)}}</dd><dt>utm_content</dt><dd>{{utmContent(r)||'—'}}</dd><dt>Phòng / nhóm</dt><dd>{{r.department||'—'}}</dd><dt>Người phụ trách</dt><dd>{{r.assignee_name||'Chưa phân công'}}</dd><dt>Tình trạng</dt><dd>{{r.registration_status==='invited'?'Đã mời':'Đã đăng ký'}}</dd><dt>Gọi xác nhận</dt><dd>{{callLabel(r.call_status)}}</dd><dt>Phản hồi</dt><dd>{{responseLabel(r.contact_response)}}</dd></dl><MButton v-if="r.can_edit" variant="secondary" class="mt-3" @click="run(()=>openContact(r))">Cập nhật liên hệ</MButton></article><MEmptyState v-if="!s.rows.length" type="no-result" title="Không có đăng ký phù hợp"/></section><ListPager :page="s.page" :page-size="s.pageSize" :total="s.rowTotal" :loading="s.rowsBusy" @update:page-size="s.pageSize=$event" @update:page="s.page=$event;run(loadRows)"/></template>
<ImportFields v-else-if="s.route==='nguon-du-lieu'" mobile/><SettingsFields v-else-if="s.route==='muc-tieu'"/></template></main>
<MDialog v-model="sheetOpen" :title="sheetTitle" presentation="sheet" width="640px">
<div v-if="sheet==='actions'" class="mobile-report-menu stack">
<MButton variant="secondary" @click="sheet='filters'"><template #icon><MIcon name="filter" :size="20"/></template>Bộ lọc báo cáo<span v-if="reportFilterCount"> ({{reportFilterCount}})</span></MButton>
<MButton v-if="!s.filters.snapshot" variant="secondary" :loading="s.refreshBusy" :disabled="s.reportBusy" @click="refresh"><template #icon><MIcon name="refresh" :size="20"/></template>Cập nhật ngay</MButton>
<MButton variant="secondary" :disabled="!s.report||s.reportBusy" @click="sheet='metadata'">Thông tin dữ liệu</MButton>
<div v-if="s.reportTab!=='targets'" class="stack mobile-display-settings"><h3>Hiển thị báo cáo</h3><MCheckbox v-model="s.showPercent" label="Hiển thị % trên biểu đồ"/><MCheckbox v-for="report in reports" :key="report.value" :model-value="s.selected.includes(report.value)" :label="report.label" @update:model-value="s.selected=$event?[...s.selected,report.value]:s.selected.filter(v=>v!==report.value)"/></div>
<MButton v-if="canCreateEvent" variant="secondary" @click="create">Tạo sự kiện</MButton>
</div>
<ReportFilters v-else-if="sheet==='filters'" open compact/>
<RegistrationFilters v-else-if="sheet==='rows'" fields-only/>
<ReportStamp v-else-if="sheet==='metadata'" open/>
<template #footer><MButton v-if="sheet==='filters'||sheet==='rows'" variant="secondary" @click="sheet==='filters'?resetFilters():resetRowFilters()">Xóa bộ lọc</MButton><MButton variant="primary" @click="sheet=''">{{sheet==='filters'||sheet==='rows'?'Xem kết quả':'Xong'}}</MButton></template>
</MDialog>
<footer v-if="!more&&s.route==='muc-tieu'&&canEdit" class="sticky-actions"><MButton variant="secondary" @click="run(()=>selectEvent(s.event.id))">Hủy</MButton><MButton variant="primary" :loading="s.busy" @click="run(saveEvent)">Lưu</MButton></footer><MMobileBottomNav :items="items.filter(i=>i.key==='more'||visibleNav.some(n=>n.key===i.key))" :active="more?'more':s.route" @select="go"/></div></template>
